// Playlist: https://www.shadertoy.com/playlist/mfdGWj

// Recreating some illustrations from Eric Lengyel's "Projective Geometric Algebra Illuminated".

#define OUTLINE_OUTER_WIDTH .03
#define OUTLINE_INNER_WIDTH .01

#define M2PI 6.28318530718

#if HW_PERFORMANCE==0
#define AA 1
#else
#define AA 2   // make this 2 or 3 for antialiasing
#endif


struct bivec3 {
    vec3 v;
    vec3 m;
};

float wedge(vec2 a, vec2 b) {
    return (a.x*b.y - a.y*b.x);    
}

// A plane joins three points
vec4 join(vec3 p, vec3 q, vec3 r) {
    vec4 trivec;
    trivec.xyz = cross(q - p, r - p); // plane normal
    trivec.w = -dot(trivec.xyz, p); // plane offset
    return trivec;
}

// A line joins two points
bivec3 join(vec4 p, vec4 q) {
    bivec3 l;
    l.v.x = wedge(p.wx, q.wx);
    l.v.y = wedge(p.wy, q.wy);
    l.v.z = wedge(p.wz, q.wz);
    l.m.x = wedge(p.yz, q.yz);
    l.m.y = wedge(p.zx, q.zx);
    l.m.z = wedge(p.xy, q.xy);
    return l;
}

// https://www.shadertoy.com/view/43Kyzz
// A line and a plane meet at a point.
vec4 meet(bivec3 l, vec4 g) {
    vec4 pt;
    pt.xyz = -cross(g.xyz, l.m) + g.w * l.v;
    pt.w = -dot(g.xyz, l.v);
    return pt;
}

// https://www.shadertoy.com/view/43Vyzh
// The scalar orientation found by meeting to lines together
float meet(bivec3 l, bivec3 k)
{
    return -dot(l.v, k.m) -dot(l.m, k.v);
}

// New: the point at which a line meets a triangle
vec4 meetLineTriangle(bivec3 l, vec3 a, vec3 b, vec3 c) {
    vec4 e4 = vec4(0.,0.,0.,1.0);

    // assume the line is unitized so that ||l.v|| = 1.
    float lenL = length(l.v);
    l.v /= lenL;
    l.m /= lenL;

    // Translate the vertex a to the origin, and subtract a from b and c. 
    b -= a;
    c -= a;

    // Translate the line by subtracting cross(a, l.v) from it's moment, l.m
    l.m -= cross(a, l.v); // is this supposed to be cross, or product?

    // lines representing the edges...
    bivec3 k1 = join(e4, vec4(b, 1.0)); // k1 = e4 ∧ b -> e41, e42, e43
    bivec3 k2 = join(vec4(b, 1.0), vec4(c, 1.0)); // k2 = b ∧ c 
    bivec3 k3 = join(vec4(c, 1.0), e4); // k3 = c ∧ e4 -> e41, e42, e43
    // Note, the moments of k1 and k3 are zero because they contain the origin.

    // Calculate l∨k1, l∨k2, and l∨k3. If any one of these products is negative, then 
    // the line does not intersect the triangle.
    vec3 mlk = vec3(
      meet(l, k1),
      meet(l, k2),
      meet(l, k3)
    );
    bool hitFront = all(greaterThan(mlk, vec3(0.0)));
    bool hitBack = all(lessThan(mlk, vec3(0.0)));

    // Determine the plane g containing the translated triangle by calculating g=e4∧b∧c
    vec4 g = join(e4.xyz, b.xyz, c.xyz); // this plane contains the origin, so g.w is 0

    // The point r where g and l meet is given by:
    vec4 r = meet(l, g);

    // after unitizing this point, offset by a to get
    vec3 q = (r.xyz / r.w) + a;

    float hitStatus = hitFront || hitBack ? 1.0 : -1.0;
    return vec4(q, hitStatus);
}



struct Payload {
    float d; // distance
    vec3 albedo; // albedo
};

const float lineThickness = .005;
const float arrowThickness = .01;
const float arrowCapWidth = .06;
const float arrowCapHeight = .12;

const float xLength = 2.0;
const float yLength = 2.0;
const float wLength = 2.0;
const float wPlaneHeight = 1.0;

void getTriangle(out vec2 a, out vec2 b, out vec2 c) {
    float s = 0.3; // speed of animation

    //vec3 rotationAxis = vec3(1.0, sin(iTime * s) * .5, 1.0);
    vec2 up = vec2(1.0, 0.0);
    vec2 right = vec2(0.0, 1.0);
    a = up * sin(iTime * s * .5 + M2PI * .33) + right * cos(iTime * s * .5 + M2PI * .33);
    b = up * sin(iTime * s * .5 + M2PI * .66) + right * cos(iTime * s * .5 + M2PI * .66);
    c = up * sin(iTime * s * .5 + M2PI * .99) + right * cos(iTime * s * .5 + M2PI * .99);
}



void getLine(out vec3 p, out vec3 q) {
    float s = .4; // speed of animation



    p = vec3(sin(iTime * s)*.7, sin(iTime * s*-1.1)*.7, -1.0);
    q = p + vec3(0., +.0, +2.5);

    //vec3 del = vec3(-0.6, +.3, 0.0);
    //p+=del;
    //q+=del;

}

Payload map(in vec3 ro, vec3 rd, bool showCone) {
    Payload res;
    res.d = 1e38f;
    res.albedo = vec3(0.0);

    // Triangle
    vec2 a, b, c;
    getTriangle(a, b, c);
    vec3 a3 = vec3(a, 0.0), b3 = vec3(b, 0.0), c3 = vec3(c, 0.0);

    // Plane containing triangle
    vec4 g = join(a3, b3, c3);

    // Line L
    vec3 lp, lq;
    getLine(lp, lq);

    // Line in bivector form
    bivec3 l = join(vec4(lp, 1.0), vec4(lq, 1.0));

    // Meet the line and plane together
    vec4 ptAndEdgeMeets = meetLineTriangle(l, a3, b3, c3);
    float edgeMeet = ptAndEdgeMeets.w;
    vec3 pt = ptAndEdgeMeets.xyz;



    vec4 e4 = vec4(0.,0.,0.,1.0);
    // lines representing the edges...
    bivec3 k[3];
    k[0] = join(vec4(a3, 1.0), vec4(b3, 1.0));
    k[1] = join(vec4(b3, 1.0), vec4(c3, 1.0));
    k[2] = join(vec4(c3, 1.0), vec4(a3, 1.0));

    vec3 mlk = vec3(
      meet(l, k[0]),
      meet(l, k[1]),
      meet(l, k[2])
    );


    float minMt = 1e38f;

    vec3 ch = rd * .1;

    // Visualize triangle edges
    {        
        // Opaque outline
        float d = 1e38f;

        d = min(d, sdArrow( ro+ch, a3, b3 - normalize(b3-a3)*arrowCapHeight, arrowThickness, arrowCapWidth, arrowCapHeight*1.1 ));

        for (int i = 0; i < 3; ++i) {
            float lmk = meet(l, k[i]);
            minMt = min(minMt, lmk);
        }


        d = min(d, sdArrow( ro+ch, b3, c3 - normalize(c3-b3)*arrowCapHeight, arrowThickness, arrowCapWidth, arrowCapHeight*1.1 ));
        d = min(d, sdArrow( ro+ch, c3, a3 - normalize(a3-c3)*arrowCapHeight, arrowThickness, arrowCapWidth, arrowCapHeight*1.1 )); 

        if (d < res.d) {res.d = d; res.albedo = emerald;}
    }



    // Visualize how the line of the ray meets the lines of the triangle.
    {
        vec3 ld = normalize(lq - lp);

        vec3 up = vec3(0.0, 0.0, 1.0);
        vec3 n = normalize(cross(b3-a3, c3-a3));

        vec3 mtp = mtcTriangleQuery(lp, ld, a3, b3, c3);

        vec2 mts1 = mtcSegmentQuery(lp, ld, a3, b3);
        vec2 mts2 = mtcSegmentQuery(lp, ld, b3, c3);
        vec2 mts3 = mtcSegmentQuery(lp, ld, c3, a3);

        vec3 mtp1 = mix(a3, b3, mts1.y);
        vec3 mtp2 = mix(b3, c3, mts2.y);
        vec3 mtp3 = mix(c3, a3, mts3.y);






        // Visualize the point where the ray and triangle meet
        {

            float sigmoid = 1.f / (1.f + exp(-minMt));
            vec3 color = mix(purple, blue, sigmoid);

            if (/*edgeMeet < 0.0 &&*/ showCone) {
                //float d4 = sdSolidAngle(ro + ch, lp, ld, normalize(mtp - lp)*distance(pt, lp) + lp);// - .01;
                //float d4 = sdSolidAngle(ro, lp, ld, mtp );// - .001;
                //if( d4 < res.d ) { res.d = d4; res.albedo = color; }

                //float d2 = sdSphere(ro - mtp1, .05);
                //if (d2 < res.d) {res.d = d2; res.albedo = color;} 
            }



            //vec3 color = (edgeMeet < 0.0) ? purple : blue;


            float d1 = sdArrow(ro, lp, lq, arrowThickness, arrowCapWidth, arrowCapHeight*1.1);
            if (d1 < res.d) {res.d = d1; res.albedo = black;}

            float d2 = sdSphere(ro - pt, .05);
            if (d2 < res.d) {res.d = d2; res.albedo = color;}
        }


        {
            float rotAngle = 3.14*.5;//acos(dot(ld, up));   
            //vec3 rotationAxis = normalize(cross(ld, up));        
            vec3 rotationAxis = vec3(normalize(mtp1 - pt));
            mat3 rot = transpose(rotationMatrix(rotationAxis, rotAngle));


            float sigmoid = 1.f / (1.f + exp(-mlk.x));
            vec3 color = mix(purple, blue, sigmoid);


            {
                //float d1 = sdCapsule( ro, pt, mtp1, lineThickness );
                //if (d1 < res.d) {res.d = d1; res.albedo = color; }

                vec3 delta = rot*(ro - mtp1);
                //float halfAngle = acos(dot(normalize(mtp1-lp), ld));
                //float halfAngle = acos(dot(normalize(cross(ld, mtp-pt)), ld));

                float torusRadius = .3; //halfAngle * distance(pt, lp);

                float d2 = sdTorusXY( delta, vec2(torusRadius, .01));
                if (d2 < res.d) {res.d = d2; res.albedo = color;}

                float s = -2.f;
                float t = iTime + 10.5;
                float t0 = t * s;
                float t1 = (t + .1) * s;
                vec3 pt1OnTorus = vec3(sin(t0), cos(t0), 0.0) * torusRadius;
                vec3 pt2OnTorus = vec3(sin(t1), cos(t1), 0.0) * torusRadius;
                vec3 dir = normalize(pt2OnTorus - pt1OnTorus);

                // Visualize the winding order around the torus
                float d3 = sdArrow(delta, pt1OnTorus, pt1OnTorus + dir * torusRadius * 2., arrowThickness, arrowCapWidth, arrowCapHeight*1.1);
                if (d3 < res.d) {res.d = d3; res.albedo = color;}
            }
        }


        {
            float rotAngle = 3.14*.5;//acos(dot(ld, up));   
            //vec3 rotationAxis = normalize(cross(ld, up));        
            vec3 rotationAxis = vec3(normalize(mtp2 - pt));
            mat3 rot = transpose(rotationMatrix(rotationAxis, rotAngle));



            float sigmoid = 1.f / (1.f + exp(-mlk.y));
            vec3 color = mix(purple, blue, sigmoid);


            {
                //float d1 = sdCapsule( ro, pt, mtp2, lineThickness );
                //if (d1 < res.d) {res.d = d1; res.albedo = color; }

                vec3 delta = rot*(ro - mtp2);
                //float halfAngle = acos(dot(normalize(mtp2-lp), ld));
                //float halfAngle = acos(dot(normalize(cross(ld, mtp-pt)), ld));

                float torusRadius = .3;//halfAngle * distance(pt, lp);

                float d2 = sdTorusXY( delta, vec2(torusRadius, .01));
                if (d2 < res.d) {res.d = d2; res.albedo = color;}

                float s = -2.f;
                float t = iTime + 9.5;
                float t0 = t * s;
                float t1 = (t + .1) * s;
                vec3 pt1OnTorus = vec3(sin(t0), cos(t0), 0.0) * torusRadius;
                vec3 pt2OnTorus = vec3(sin(t1), cos(t1), 0.0) * torusRadius;
                vec3 dir = normalize(pt2OnTorus - pt1OnTorus);

                // Visualize the winding order around the torus
                float d3 = sdArrow(delta, pt1OnTorus, pt1OnTorus + dir * torusRadius * 2., arrowThickness, arrowCapWidth, arrowCapHeight*1.1);
                if (d3 < res.d) {res.d = d3; res.albedo = color;}
            }
        }


        {
            float rotAngle = 3.14*.5;//acos(dot(ld, up));   
            //vec3 rotationAxis = normalize(cross(ld, up));        
            vec3 rotationAxis = vec3(normalize(mtp3 - pt));
            mat3 rot = transpose(rotationMatrix(rotationAxis, rotAngle));



            float sigmoid = 1.f / (1.f + exp(-mlk.z));
            vec3 color = mix(purple, blue, sigmoid);


            {
                //float d1 = sdCapsule( ro, pt, mtp3, lineThickness );
                //if (d1 < res.d) {res.d = d1; res.albedo = color; }

                vec3 delta = rot*(ro - mtp3);
                //float halfAngle = acos(dot(normalize(mtp3-lp), ld));
                //float halfAngle = acos(dot(normalize(cross(ld, mtp-pt)), ld));

                float torusRadius = .3;//halfAngle * distance(pt, lp);

                float d2 = sdTorusXY( delta, vec2(torusRadius, .01));
                if (d2 < res.d) {res.d = d2; res.albedo = color;}

                float s = -2.f;
                float t = iTime + 20.5;
                float t0 = t * s;
                float t1 = (t + .1) * s;
                vec3 pt1OnTorus = vec3(sin(t0), cos(t0), 0.0) * torusRadius;
                vec3 pt2OnTorus = vec3(sin(t1), cos(t1), 0.0) * torusRadius;
                vec3 dir = normalize(pt2OnTorus - pt1OnTorus);

                // Visualize the winding order around the torus
                float d3 = sdArrow(delta, pt1OnTorus, pt1OnTorus + dir * torusRadius * 2., arrowThickness, arrowCapWidth, arrowCapHeight*1.1);
                if (d3 < res.d) {res.d = d3; res.albedo = color;}
            }
        }

    }

    return res;
}

vec4 over(vec4 a, vec4 b) {
  vec4 result;
  result.a = a.a + b.a * (1.f - a.a);
  if (result.a == 0.f)
    return a;   // avoid NaN
  result.rgb = (a.rgb * a.a + b.rgb * b.a * (1.f - a.a)) / result.a;
  return result;
}

vec3 scene(in vec3 ro,in vec3 rd, bool showCone) {
    vec3 col = vec3(1.0);		// initialize color return value

    vec3 roStart = ro;

    #define NHITS 2
    vec4 tuvs[NHITS];

    for (int i = 0; i < NHITS; ++i) tuvs[i].xw = vec2(1e38f, i);  

    vec2 a, b, c;
    getTriangle(a, b, c);
    vec3 a3 = vec3(a, 0.0), b3 = vec3(b, 0.0), c3 = vec3(c, 0.0);

    // a reference ray-triangle intersection test.
    tuvs[0].xyz = triIntersect(ro, rd, a3, b3, c3);


    Payload payload;

    float rm = 1e38f; 			// tracker for minimum ray value
    float tmin = 15.0;
    float tmax = 25.0;
    float t = tmin;
    ro = roStart + t * rd;

    for (int i =0; i<50; i++) {
        payload = map(ro, rd, showCone);
        rm = min(payload.d, rm);

        //check if a ray has passed through an outline region
        if (payload.d > rm && rm < OUTLINE_OUTER_WIDTH){
            col = vec3(0); //outline
            break;
        }

        if (payload.d < OUTLINE_INNER_WIDTH) {
            //color based on suface location
            col = payload.albedo;
            break;
        }

        t += payload.d;
       	ro = roStart + t * rd;//*0.85;
        if (t > tmax) break;
    }

    tuvs[1].x = t;

    vec4 bgcol = vec4(col, 1.0);

    // Sort by hit depth
    if (tuvs[0].x < tuvs[1].x) {
        vec4 tmp = tuvs[0];
        tuvs[0] = tuvs[1];
        tuvs[1] = tmp;
    }



    // Composite the W=1 plane
    vec4 rgba = vec4(1.0, 1.0, 1.0, .0);
    if( tuvs[0].x>0.0)
    {
        vec4 geoCol;
        if (tuvs[0].w == 0.0) geoCol = vec4(green, .8);
        else if (tuvs[0].w == 1.0) geoCol = vec4(col, 1.0);
        rgba = over(geoCol, rgba);
    }
    if( tuvs[1].x>0.0)
    {
        vec4 geoCol;
        if (tuvs[1].w == 0.0) geoCol = vec4(green, .8);
        else if (tuvs[1].w == 1.0) geoCol = vec4(col, 1.0);
        rgba = over(geoCol, rgba);
    }

    return rgba.rgb;
}

mat3 lookAt(in vec3 eye, in vec3 tar, in float r){
    vec3 cw = normalize(tar - eye);// camera w
    vec3 cp = vec3(sin(r), cos(r), 0.0);// camera up
    vec3 cu = normalize(cross(cw, cp));// camera u
    vec3 cv = normalize(cross(cu, cw));// camera v
    return mat3(cu, cv, cw);
}


void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec3 tot = vec3(0.0);

    // camera
    float an = .2 + -5.0*iMouse.x/iResolution.x;

    float dist = 18.f;
    float fov = 5.f;

    vec3  ro = dist * /*vec3(0.0, .0, 1.0);// **/ vec3(cos(3.0*an), .2, sin(3.0*an));
    vec3  ta = vec3(0.0,0.0,0.0);

    // camera matrix
    vec3 ww = normalize( ta - ro );
    vec3 uu = normalize( cross(ww,vec3(0.0,1.0,0.0) ) );
    vec3 vv = normalize( cross(uu,ww));

    for( int m=0; m<AA; m++ )
    for( int n=0; n<AA; n++ )
    {           
        //create p for ray based on AA settings
        vec3 p = vec3((-iResolution.xy + 2.0*(fragCoord.xy-0.5+(vec2(float(m),float(n))+0.5)/float(AA))) / iResolution.y,2.0);


        //create view ray from vector p
        vec3 rd = lookAt(ro, ta, 0.)*normalize(vec3(p.xy, 1.0/radians(fov)));// ray direction

        ivec2 samp = ivec2(fragCoord)*AA + ivec2(m,n);
        bool showSurface = ((samp.x&1)+(samp.y&1))!=0; // 75% opaque

        //render scene
        vec3 col = scene(ro,rd, showSurface);

        //vignette
        //col -= 0.2*length(p.xy);

        tot += col;
    }
    tot /= float(AA*AA);
    fragColor = vec4( tot, 1.0 );
}

const vec3 black = vec3(0.)/255.;
const vec3 white = vec3(255.)/255.;
const vec3 lightGray = vec3(205.)/255.;
const vec3 mediumGray = vec3(140.)/255.;
const vec3 darkGray = vec3(94.)/255.;

const vec3 green = vec3(118., 185.,0.)/255.;
const vec3 emerald = vec3(0.,133.,100.)/255.;
const vec3 blue = vec3(0.,113.,197.)/255.;
const vec3 purple = vec3(93.,22.,130.)/255.;
const vec3 yellow = vec3(250.,194.,0.)/255.;
const vec3 garnet = vec3(137.,12.,88.)/255.;

vec3 parallelogramIntersect( in vec3 ro, in vec3 rd, in vec3 v0, in vec3 v1, in vec3 v2 )
{
    vec3 a = v0 - v1;
    vec3 b = v2 - v0;
    vec3 p = v0 - ro;

    vec3 n = cross( a, b );
    vec3 q = cross( rd, p );

    float i = 1.0/dot( rd, n );

    float u = dot( q, a )*i;
    float v = dot( q, b )*i;
    float t = dot( n, p )*i;

    if( u<0.0 || u>1.0 || v<0.0 || v>1.0 ) return vec3(-1.0);

    return vec3( t, u, v );
}

vec3 triIntersect( in vec3 ro, in vec3 rd, in vec3 v0, in vec3 v1, in vec3 v2 )
{
    vec3 v1v0 = v1 - v0;
    vec3 v2v0 = v2 - v0;
    vec3 rov0 = ro - v0;

#if 0
    // Cramer's rule for solcing p(t) = ro+t·rd = p(u,v) = vo + u·(v1-v0) + v·(v2-v1)
    float d = 1.0/determinant(mat3(v1v0, v2v0, -rd ));
    float u =   d*determinant(mat3(rov0, v2v0, -rd ));
    float v =   d*determinant(mat3(v1v0, rov0, -rd ));
    float t =   d*determinant(mat3(v1v0, v2v0, rov0));
#else
    // The four determinants above have lots of terms in common. Knowing the changing
    // the order of the columns/rows doesn't change the volume/determinant, and that
    // the volume is dot(cross(a,b,c)), we can precompute some common terms and reduce
    // it all to:
    vec3  n = cross( v1v0, v2v0 );
    vec3  q = cross( rov0, rd );
    float d = 1.0/dot( rd, n );
    float u = d*dot( -q, v2v0 );
    float v = d*dot(  q, v1v0 );
    float t = d*dot( -n, rov0 );
#endif    

    if( u<0.0 || v<0.0 || (u+v)>1.0 ) t = -1.0;

    return vec3( t, u, v );
}

