// Smooth Union, Subtraction and Intersection
float opSmoothUnion( float d1, float d2, float k )
{
    float h = clamp( 0.5 + 0.5*(d2-d1)/k, 0.0, 1.0 );
    return mix( d2, d1, h ) - k*h*(1.0-h);
}

float opSmoothSubtraction( float d1, float d2, float k )
{
    float h = clamp( 0.5 - 0.5*(d2+d1)/k, 0.0, 1.0 );
    return mix( d2, -d1, h ) + k*h*(1.0-h);
}

float opSmoothIntersection( float d1, float d2, float k )
{
    float h = clamp( 0.5 - 0.5*(d2-d1)/k, 0.0, 1.0 );
    return mix( d2, d1, h ) + k*h*(1.0-h);
}


//------------------------------------------------------------------
mat3 rotationMatrix(vec3 axis, float angle) {
    // Normalize the axis to ensure proper rotation
    axis = normalize(axis);

    float cosAngle = cos(angle);
    float sinAngle = sin(angle);
    float oneMinusCos = 1.0 - cosAngle;

    // Components of the rotation matrix
    float xx = axis.x * axis.x;
    float yy = axis.y * axis.y;
    float zz = axis.z * axis.z;
    float xy = axis.x * axis.y;
    float xz = axis.x * axis.z;
    float yz = axis.y * axis.z;
    float xs = axis.x * sinAngle;
    float ys = axis.y * sinAngle;
    float zs = axis.z * sinAngle;

    // Construct the rotation matrix
    return mat3(
        cosAngle + xx * oneMinusCos, xy * oneMinusCos - zs, xz * oneMinusCos + ys,
        xy * oneMinusCos + zs, cosAngle + yy * oneMinusCos, yz * oneMinusCos - xs,
        xz * oneMinusCos - ys, yz * oneMinusCos + xs, cosAngle + zz * oneMinusCos
    );
}

vec3 rotateToNormal(vec3 point, vec3 normal) {
    // Normalize the normal vector
    normal = normalize(normal);

    // Reference vector to rotate (0, 1, 0)
    vec3 refVector = point;

    // Compute the cross product (axis of rotation)
    vec3 axis = cross(refVector, normal);

    // Check if the normal is aligned with the reference vector
    float dotProd = dot(refVector, normal);

    // If the vectors are parallel, no rotation is needed
    if (abs(dotProd - 1.0) < 1e-6) {
        return refVector; // Already aligned
    }

    // If the vectors are opposite, return a perpendicular vector
    if (abs(dotProd + 1.0) < 1e-6) {
        return vec3(0.0, 0.0, 1.0); // Rotate 180 degrees around X-axis
    }

    // Compute the angle between the vectors
    float angle = acos(dotProd);

    // Build the rotation matrix using axis-angle
    float cosAngle = cos(angle);
    float sinAngle = sin(angle);
    float oneMinusCos = 1.0 - cosAngle;

    axis = normalize(axis); // Ensure the axis is a unit vector

    mat3 rotationMatrix = mat3(
        cosAngle + axis.x * axis.x * oneMinusCos, axis.x * axis.y * oneMinusCos - axis.z * sinAngle, axis.x * axis.z * oneMinusCos + axis.y * sinAngle,
        axis.y * axis.x * oneMinusCos + axis.z * sinAngle, cosAngle + axis.y * axis.y * oneMinusCos, axis.y * axis.z * oneMinusCos - axis.x * sinAngle,
        axis.z * axis.x * oneMinusCos - axis.y * sinAngle, axis.z * axis.y * oneMinusCos + axis.x * sinAngle, cosAngle + axis.z * axis.z * oneMinusCos
    );

    // Rotate the reference vector
    return rotationMatrix * refVector;
}


vec3 closestPointToLine( vec3 p, vec3 a, vec3 b, float r )
{
    vec3 pa = p-a, ba = b-a;
	float h = dot(pa,ba)/dot(ba,ba);
    vec3 q = a + ba*h;
    return q + r*normalize(p-q);
}

vec3 closestPointToCapsule( vec3 p, vec3 a, vec3 b, float r )
{
    vec3 pa = p-a, ba = b-a;
	float h = clamp( dot(pa,ba)/dot(ba,ba), 0.0, 1.0 );
    vec3 q = a + ba*h;
    return q + r*normalize(p-q);
}

// cheaper alternative to acos intrinsic
// https://developer.download.nvidia.com/cg/acos.html
float swacos(float x) {
  float negate = float(x < 0.f);
  x = abs(x);
  float ret = -0.0187293f;
  ret = ret * x;
  ret = ret + 0.0742610f;
  ret = ret * x;
  ret = ret - 0.2121144f;
  ret = ret * x;
  ret = ret + 1.5707288f;
  ret = ret * sqrt(1.f-x);
  ret = ret - 2.f * negate * ret;
  return negate * 3.14159265358979f + ret;
}

// Given an angular similarity, returns the corresponding angle in radians. 
//   s - the similarity measure, s = (dot(d, ∆) |dot(d, ∆)| / |∆|^2)
float similarityToAngle(float s) {
    if (0.f <= s && s <= 1.f) {
        return swacos(2.f * s - 1.0) / 2.0;
    }
    else if (-1.f <= s) {
        return (swacos(2.f * s + 1.0) / 2.0) + radians(90.);
    }
}

// Returns the angular similarity between two directions. 
// Similarity is expressed as s = dot(d, ∆) |dot(d, ∆)| / |∆|^2
//  d - the direction of a ray
//  ∆ - a vector relative to ray's origin. (∆ = p - o)
float angularSimilarity(vec3 d, vec3 delta) {    
    // length squared of delta
    float deltaNorm2 = dot(delta, delta);

    // proportional to cos(theta) between d and ∆
    float dDotDelta = dot(d, delta);

    // similarity = dot(d, ∆) |dot(d, ∆)| / |∆|^2
    return dDotDelta * abs(dDotDelta) / deltaNorm2;
}

vec3 angleAxis(float angle, vec3 axis, vec3 v) {
    vec3 k = normalize(axis); // Ensure the axis is a unit vector
    float cosTheta = cos(angle);
    float sinTheta = sin(angle);

    // Rodrigues' rotation formula
    vec3 rotated = v * cosTheta + 
                   cross(k, v) * sinTheta + 
                   k * dot(k, v) * (1.0 - cosTheta);

    return rotated;
}

// Returns a maximal angular similarity to the segment relative to the cone, 
// as well as the parameterization "t" along the segment to the corresponding point. 
// Similarity is expressed as s = dot(d, ∆) |dot(d, ∆)| / |∆|^2
//  a  - the apex of the cone
//  d  - the direction of the cone, perpendicular to it's base.
//  v0 - the starting point of the segment
//  v1 - the ending point of the segment
vec2 mtcSegmentQuery(vec3 a, vec3 d, vec3 v0, vec3 v1)
{
    //  ∆0 and ∆1 are vectors from segment to the apex
    vec3 d0 = v0 - a;
    vec3 d1 = v1 - a;

    // α - angle between d and ∆0
    // β - angle between d and ∆1
    // γ - angle between ∆0 and ∆1
    // θ - minimizing angle between D and the segment

    // Values are:

    // |∆0|^2
    float dd00 = dot(d0, d0);

    // |∆1|^2
    float dd11 = dot(d1, d1);

    // |∆0||D|cos(α)
    float dd0d = dot(d0, d);

    // |∆1||D|cos(β)
    float dd1d = dot(d1, d);

    // |∆0||∆1|cos(γ)
    float dd01 = dot(d0, d1);

    // Vector perpendicular to triangle from edge to apex, scaled by parallelogram.
    // Equivalent to great circle normal connecting ∆0 and ∆1, but scaled.
    // |∆0x∆1| = |∆0||∆1|sin(γ)
    vec3 n = cross(d0, d1);

    // |N|^2
    float dnn = dot(n, n);

    // |D||N|cos(θ)
    float ddn = dot(d, n);

    // Project d onto plane containing the triangle.
    // (aka, project point onto great circle containing arc from v0 to v1)
    // p = D - (D·N)/(N·N) * N
    vec3 d2 = d - (ddn / dnn) * n;

    // Find planes perpendicular to great circle containing the arc
    // (using triple vector product rule to avoid cross products)
    //   A × (B × C) = B (A · C) − C (A · B),
    //   (A × B) × C = C (A · B) - B (A · C),
    //   N0 = Nx∆0 = (∆0x∆1)x∆0 = ∆1(∆0·∆0) - ∆0(∆0·∆1)
    //   N1 = Nx∆1 = (∆0x∆1)x∆1 = ∆0(∆1·∆1) - ∆1(∆0·∆1)
    vec3 n0 = d1 * dd00 - d0 * dd01;
    vec3 n1 = d0 * dd11 - d1 * dd01;

    // Test if projection falls outside the arc 
    if (dot(d2, n0) < 0.f || dot(d2, n1) < 0.f) {
        // Compute angular similarity measure to the end points
        // similarity = dot(d, ∆) |dot(d, ∆)| / |∆|^2
        float sa = dd0d * abs(dd0d) / dd00;
        float sb = dd1d * abs(dd1d) / dd11;

        // Pick the closer of the two ends
        if (sa > sb) return vec2(sa, 0.);
        else return vec2(sb, 1.);
    }

    // Projection is on the triangle / within the arc.
    // Compute the barycentrics of the projected point within 
    // that triangle to recover the "t" parameter interpolating the edge.
    float d20 = dot(d2,d0);
    float d21 = dot(d2,d1);
    float dd2 = dot(d, d2);
    float d22 = dot(d2, d2);    
    float area = (dd00*dd11 - dd01*dd01);
    float v = ((dd11*d20) - (dd01*d21)) / area;    
    float w = ((dd00*d21) - (dd01*d20)) / area;
    float t = w / (w + v);

    // similarity = dot(d, ∆) |dot(d, ∆)| / |∆|^2
    float s = dd2 * abs(dd2) / d22;
    return vec2(s, t);
}



// Returns { s, t, u, v }
// Returns a maximal angular similarity to the surface of the triangle relative to the cone, 
// as well as the varycentrics "u" and "v" along the triangle to the corresponding point. 
// Similarity is expressed as s = dot(d, ∆) |dot(d, ∆)| / |∆|^2
//  a  - the apex of the cone
//  d  - the direction of the cone, perpendicular to it's base.
//  v0 - the 1st tri vertex, corresponds to 1 - u - v
//  v1 - the 2nd tri vertex, corresponds to u
//  v2 - the 3rd tri vertex, corresponds to v
vec3 mtcTriangleQuery(vec3 a, vec3 d, vec3 v0, vec3 v1, vec3 v2)
{   
    vec2 st0 = mtcSegmentQuery(a, d, v0, v1);
    vec2 st1 = mtcSegmentQuery(a, d, v1, v2);
    vec2 st2 = mtcSegmentQuery(a, d, v2, v0);

    if (st0.x >= st1.x && st0.x >= st2.x) {
        return mix(v0, v1, st0.y);
    }
    if (st1.x >= st0.x && st1.x >= st2.x) {
        return mix(v1, v2, st1.y);
    }
    if (st2.x >= st1.x && st2.x >= st0.x) {
        return mix(v2, v0, st2.y);
    }
    return a;
}

float sdSolidAngle(vec3 p, vec3 a, vec3 d, vec3 b) {
    // Length of the side of the solid angle conic
    float ra = distance(a, b);    

    // The angle between the direction of the conic and a point
    // on the base.
    float s = angularSimilarity(d, b-a);
    float ang = similarityToAngle(clamp(s, 0.0, 1.0));

    // Transform query point s.t. apex is origin
    p = p-a;

    // Rotate query point such that conic direction is aligned to "y"
    vec3 yAxis = vec3(0, 1, 0);
    vec3 rotAxis = cross(d, yAxis);
    float rotAngle = acos(dot(yAxis, d));
    vec3 pRot = angleAxis(rotAngle, rotAxis, p);

    // Now compute the SDF as before with the rotated point
    vec2 q = vec2( length(pRot.xz), pRot.y );

    vec2 c = vec2(sin(ang), cos(ang)); 
    float l = length(q) - ra;
    float m = length(q - c*clamp(dot(q,c),0.0,ra) );
    return max(l,m*sign(c.y*q.x-c.x*q.y));
}

vec3 lineSegmentQuery(in vec3 ro, in vec3 rd, in vec3 s0, in vec3 s1)
{
    vec3 sd = s1 - s0;
    vec3 diff = ro - s0;

    float rdLen2 = dot(rd, rd);
    float sdLen2 = dot(sd, sd);
    float raySegmentDot = -dot(rd, sd);
    float rayStartDot = dot(rd, diff);
    float segmentStartDot = -dot(sd, diff);

    float det = max(rdLen2 * sdLen2 - raySegmentDot * raySegmentDot, 0.0);

    float tRay = 0.0;
    float tSegment = 0.0;

    if (det > 0.0) {
        tSegment = (raySegmentDot * rayStartDot - rdLen2 * segmentStartDot) / det;
        tSegment = clamp(tSegment, 0.0, 1.0); // Ensure tSegment is within the segment bounds
        tRay = (raySegmentDot * segmentStartDot - sdLen2 * rayStartDot) / det;
    } else {
        // Handle the case when determinant is zero or negative
        tRay = -rayStartDot / rdLen2;
    }

    vec3 closestPointOnRay = ro + tRay * rd;
    vec3 closestPointOnSegment = s0 + tSegment * sd;
    vec3 differenceVector = closestPointOnRay - closestPointOnSegment;
    float diffLen2 = dot(differenceVector, differenceVector);

    return vec3(diffLen2, tRay, tSegment);
}


// Returns the "st" parameters defining the closest points between two segments. 
//  P0 / P1 - the start and end points for the first segment
//  Q0 / Q1 - the start and end points for the second segment
vec2 segmentSegmentQuery(vec3 P0, vec3 P1, vec3 Q0, vec3 Q1) {
    vec3 P1mP0 = P1 - P0;
    vec3 Q1mQ0 = Q1 - Q0;
    vec3 P0mQ0 = P0 - Q0;
    float a = dot(P1mP0, P1mP0);
    float b = dot(P1mP0, Q1mQ0);
    float c = dot(Q1mQ0, Q1mQ0);
    float d = dot(P1mP0, P0mQ0);
    float e = dot(Q1mQ0, P0mQ0);
    float det = a * c - b * b;
    float s, t, nd, bmd, bte, ctd, bpe, ate, btd;

    if (det > 0.)
    {
        bte = b * e;
        ctd = c * d;
        if (bte <= ctd)  // s <= 0
        {
            s = 0.;
            if (e <= 0.)  // t <= 0
            {
                // region 6
                t = 0.;
                nd = -d;
                if (nd >= a)
                {
                    s = 1.;
                }
                else if (nd > 0.)
                {
                    s = nd / a;
                }
                // else: s is already zero
            }
            else if (e < c)  // 0 < t < 1
            {
                // region 5
                t = e / c;
            }
            else  // t >= 1
            {
                // region 4
                t = 1.;
                bmd = b - d;
                if (bmd >= a)
                {
                    s = 1.;
                }
                else if (bmd > 0.)
                {
                    s = bmd / a;
                }
                // else:  s is already zero
            }
        }
        else  // s > 0
        {
            s = bte - ctd;
            if (s >= det)  // s >= 1
            {
                // s = 1
                s = 1.;
                bpe = b + e;
                if (bpe <= 0.)  // t <= 0
                {
                    // region 8
                    t = 0.;
                    nd = -d;
                    if (nd <= 0.)
                    {
                        s = 0.;
                    }
                    else if (nd < a)
                    {
                        s = nd / a;
                    }
                    // else: s is already one
                }
                else if (bpe < c)  // 0 < t < 1
                {
                    // region 1
                    t = bpe / c;
                }
                else  // t >= 1
                {
                    // region 2
                    t = 1.;
                    bmd = b - d;
                    if (bmd <= 0.)
                    {
                        s = 0.;
                    }
                    else if (bmd < a)
                    {
                        s = bmd / a;
                    }
                    // else:  s is already one
                }
            }
            else  // 0 < s < 1
            {
                ate = a * e;
                btd = b * d;
                if (ate <= btd)  // t <= 0
                {
                    // region 7
                    t = 0.;
                    nd = -d;
                    if (nd <= 0.)
                    {
                        s = 0.;
                    }
                    else if (nd >= a)
                    {
                        s = 1.;
                    }
                    else
                    {
                        s = nd / a;
                    }
                }
                else  // t > 0
                {
                    t = ate - btd;
                    if (t >= det)  // t >= 1
                    {
                        // region 3
                        t = 1.;
                        bmd = b - d;
                        if (bmd <= 0.)
                        {
                            s = 0.;
                        }
                        else if (bmd >= a)
                        {
                            s = 1.;
                        }
                        else
                        {
                            s = bmd / a;
                        }
                    }
                    else  // 0 < t < 1
                    {
                        // region 0
                        s /= det;
                        t /= det;
                    }
                }
            }
        }
    }
    else
    {
        // The segments are parallel. The quadratic factors to
        //   R(s,t) = a*(s-(b/a)*t)^2 + 2*d*(s - (b/a)*t) + f
        // where a*c = b^2, e = b*d/a, f = |P0-Q0|^2, and b is not
        // zero. R is constant along lines of the form s-(b/a)*t = k
        // and its occurs on the line a*s - b*t + d = 0. This line
        // must intersect both the s-axis and the t-axis because 'a'
        // and 'b' are not zero. Because of parallelism, the line is
        // also represented by -b*s + c*t - e = 0.
        //
        // The code determines an edge of the domain [0,1]^2 that
        // intersects the minimum line, or if none of the edges
        // intersect, it determines the closest corner to the minimum
        // line. The conditionals are designed to test first for
        // intersection with the t-axis (s = 0) using
        // -b*s + c*t - e = 0 and then with the s-axis (t = 0) using
        // a*s - b*t + d = 0.

        // When s = 0, solve c*t - e = 0 (t = e/c).
        if (e <= 0.)  // t <= 0
        {
            // Now solve a*s - b*t + d = 0 for t = 0 (s = -d/a).
            t = 0.;
            nd = -d;
            if (nd <= 0.)  // s <= 0
            {
                // region 6
                s = 0.;
            }
            else if (nd >= a)  // s >= 1
            {
                // region 8
                s = 1.;
            }
            else  // 0 < s < 1
            {
                // region 7
                s = nd / a;
            }
        }
        else if (e >= c)  // t >= 1
        {
            // Now solve a*s - b*t + d = 0 for t = 1 (s = (b-d)/a).
            t = 1.;
            bmd = b - d;
            if (bmd <= 0.)  // s <= 0
            {
                // region 4
                s = 0.;
            }
            else if (bmd >= a)  // s >= 1
            {
                // region 2
                s = 1.;
            }
            else  // 0 < s < 1
            {
                // region 3
                s = bmd / a;
            }
        }
        else  // 0 < t < 1
        {
            // The point (0,e/c) is on the line and domain, so we have
            // one point at which R is a minimum.
            s = 0.;
            t = e / c;
        }
    }

    return vec2(s, t);
}
